#!/bin/sh
# installer.record-deny.v1 - deterministic trial shim for fallback installers
# (brew/curl/npm/pip) per TASK-SPEC 2.5.2. Records the attempted invocation in
# the trial audit log, then refuses with a fixed error and exit 1.
set -u
log=${TRIAL_AUDIT_LOG:?TRIAL_AUDIT_LOG is not set}
profile='installer.record-deny.v1'
tool=${0##*/}

_json_escape() {
  _in=$1
  _esc=
  while [ -n "$_in" ]; do
    _ch=${_in%"${_in#?}"}
    _prev=$_in
    _in=${_in#?}
    [ "$_in" = "$_prev" ] && _in=
    case $_ch in
      '"') _esc="${_esc}\\\"" ;;
      '\') _esc="${_esc}\\\\" ;;

display.text:
#!/bin/sh
# installer.record-deny.v1 - deterministic trial shim for fallback installers
# (brew/curl/npm/pip) per TASK-SPEC 2.5.2. Records the attempted invocation in
# the trial audit log, then refuses with a fixed error and exit 1.
set -u
log=${TRIAL_AUDIT_LOG:?TRIAL_AUDIT_LOG is not set}
profile='installer.record-deny.v1'
tool=${0##*/}

_json_escape() {
  _in=$1
  _esc=
  while [ -n "$_in" ]; do
    _ch=${_in%"${_in#?}"}
    _prev=$_in
    _in=${_in#?}
    [ "$_in" = "$_prev" ] && _in=
    case $_ch in
      '"') _esc="${_esc}\\\"" ;;
      '\') _esc="${_esc}\\\\" ;;
      [[:cntrl:]])
        _ord=$(printf '%d' "'$_ch")
        case $_ord in
          8) _esc="${_esc}\\b" ;;
          9) _esc="${_esc}\\t" ;;
          10) _esc="${_esc}\\n" ;;
          12) _esc="${_esc}\\f" ;;
          13) _esc="${_esc}\\r" ;;
          *) _esc="${_esc}\\u00$(printf '%02x' "$_ord")" ;;
        esac
        ;;
      *) _esc="${_esc}${_ch}" ;;
    esac
  done
}

_audit() {
  _code=$1
  shift
  _seq=0
  if [ -f "$log" ]; then
    while IFS= read -r _line || [ -n "$_line" ]; do
      _seq=$((_seq + 1))
    done < "$log"
  fi
  _seq=$((_seq + 1))
  _args=
  _sep=
  for _arg in "$@"; do
    _json_escape "$_arg"
    _args="${_args}${_sep}\"${_esc}\""
    _sep=,
  done
  _json_escape "$tool"
  printf '%s\n' "{\"seq\":${_seq},\"tool\":\"${_esc}\",\"argv\":[${_args}],\"exit\":${_code},\"profile\":\"${profile}\"}" >> "$log"
}

_audit 1 "$@"
printf '%s: blocked by trial policy (installer access is disabled in this trial)\n' "$tool" >&2
exit 1

